using TutorFlow.Infrastructure.Conocimiento;

Console.OutputEncoding = Encoding.UTF8;
var opciones = new OpcionesConocimiento { DocumentosVigentes = ["reglamento_academico_2025.md", "evaluacion_y_calificaciones.md", "bienestar_y_becas.md"] };
var bc = CargadorConocimiento.Cargar(opciones);
var modo = args.Length > 0 ? args[0] : "recuperacion";

var t = typeof(BaseConocimientoEnMemoria);
var campo = t.GetField("_secciones", BindingFlags.NonPublic | BindingFlags.Instance)!;
var puntuar = t.GetMethod("Puntuar", BindingFlags.NonPublic | BindingFlags.Instance)!;
var extraer = t.GetMethod("ExtraerRaices", BindingFlags.NonPublic | BindingFlags.Static)!;
var expandir = t.Assembly.GetType("TutorFlow.Infrastructure.Conocimiento.ExpansionDeTerminos")!.GetMethod("Expandir")!;
var indexadas = ((System.Collections.IEnumerable)campo.GetValue(bc)!).Cast<object>().ToList();
var tipoIdx = indexadas[0].GetType();
var propSeccion = tipoIdx.GetProperty("Seccion")!;

List<(SeccionDocumento S, double P)> Puntajes(string pregunta)
{
    var consulta = ConsultaDeRecuperacion.DeTexto(pregunta);
    var raices = extraer.Invoke(null, [consulta])!;
    var frecs = (IReadOnlyDictionary<string, int>)raices.GetType().GetProperty("Frecuencias")!.GetValue(raices)!;
    var terminos = (IReadOnlyList<string>)expandir.Invoke(null, [frecs.Keys])!;
    return indexadas.Select(i => ((SeccionDocumento)propSeccion.GetValue(i)!, (double)puntuar.Invoke(bc, [i, terminos])!))
        .Where(x => x.Item2 > 0).OrderByDescending(x => x.Item2).ToList();
}

static string Id(SeccionDocumento s) => (s.Documento.StartsWith("reglamento") ? "R25" : s.Documento.StartsWith("eval") ? "EVAL" : "BIEN") + " " + s.Seccion;

if (modo == "recuperacion")
{
    var preguntas = new (string Etq, string Q, string[] Necesarias)[]
    {
        ("Q1", "¿Cuál es la nota mínima para aprobar una asignatura?", ["R25 Artículo 5"]),
        ("Q2", "¿Cuál es mi promedio ponderado del periodo?", ["EVAL Sección 3", "EVAL Sección 4"]),
        ("Q3", "¿Cuántas faltas tengo en Bases de Datos?", ["R25 Artículo 11"]),
        ("Q4", "¿Cómo se calcula la nota definitiva de una asignatura?", ["EVAL Sección 2", "EVAL Sección 3"]),
        ("Q5", "¿Qué nota definitiva tengo en Contabilidad?", ["EVAL Sección 3", "R25 Artículo 5"]),
        ("Q6", "¿Qué estudiantes de mi programa tienen alguna asignatura perdida?", ["R25 Artículo 5"]),
        ("Q7", "¿Cuál es el horario de atención de Bienestar?", ["BIEN Sección 1"]),
        ("Q8", "¿Qué requisitos tiene la beca por rendimiento académico?", ["BIEN Sección 3.1"]),
        ("Q9", "¿Qué dice el reglamento sobre el uso de parqueaderos?", []),
        ("Q10", "¿Cuál es la nota de Bases de Datos de Andrés Martínez?", []),
        ("C1", "¿Cuántos estudiantes tiene mi programa?", []),
        ("C2", "¿Cuál es el promedio de Valentina Castro?", []),
        ("C3", "¿Qué estudiantes están en prueba académica?", ["R25 Artículo 20"]),
        ("E-b", "¿Estoy en prueba académica?", ["R25 Artículo 20"]),
    };
    foreach (var (etq, q, nec) in preguntas)
    {
        var rs = Puntajes(q);
        var raicesP = RaicesDeContenido.De(q).ToHashSet();
        var minimo = Math.Min(2, (raicesP.Count + 1) / 2);
        var top = rs.Count > 0 ? rs[0].P : 0;
        Console.WriteLine($"\n### {etq}: {q}\nraices(r={raicesP.Count}): {string.Join(",", raicesP)}  minimoRelevancia={minimo}  mejor={top:F2}");
        Console.WriteLine("rank | seccion | puntaje | %mejor | raices compartidas | necesaria");
        var top6 = rs.Take(6).ToList();
        var i = 0;
        foreach (var (s, p) in rs)
        {
            i++;
            var rel = RaicesDeContenido.De($"{s.Titulo} {s.Texto}").Count(raicesP.Contains);
            Console.WriteLine($"{i}{(i > 6 ? "*" : "")} | {Id(s)} ({s.Titulo}) | {p:F2} | {100 * p / top:F1}% | {rel}{(rel >= minimo && raicesP.Count > 0 ? " REL" : "")} | {(nec.Contains(Id(s)) ? "NEC" : "")}");
        }
        foreach (var umbral in new[] { 30, 40, 50, 60 })
        {
            bool Rel(SeccionDocumento s) => raicesP.Count > 0 && RaicesDeContenido.De($"{s.Titulo} {s.Texto}").Count(raicesP.Contains) >= minimo;
            var entreg = top6.Where(x => 100 * x.P / top >= umbral || Rel(x.S)).Select(x => Id(x.S)).ToList();
            var sinRel = top6.Where(x => 100 * x.P / top >= umbral).Select(x => Id(x.S)).ToList();
            var falt = nec.Where(n => !entreg.Contains(n)).ToList();
            var sobra = entreg.Where(e => !nec.Contains(e)).ToList();
            Console.WriteLine($"UMBRAL {umbral}% (con excepcion relevancia): [{string.Join("; ", entreg)}] faltan=[{string.Join("; ", falt)}] sobran={sobra.Count}[{string.Join("; ", sobra)}]");
            var faltSin = nec.Where(n => !sinRel.Contains(n)).ToList();
            Console.WriteLine($"   solo-umbral (sin excepcion): [{string.Join("; ", sinRel)}] faltan=[{string.Join("; ", faltSin)}]");
        }
    }
}

