        ("Q1", "¿Cuál es la nota mínima para aprobar una asignatura?", ["R25 Artículo 5"], ["R25 Artículo 5"]),
        ("Q2", "¿Cuál es mi promedio ponderado del periodo?", ["EVAL Sección 4"], ["EVAL Sección 4", "EVAL Sección 3"]),
