        ("Q6", "¿Qué estudiantes de mi programa tienen alguna asignatura perdida?", [], ["R25 Artículo 5"]),
        ("Q7", "¿Cuál es el horario de atención de Bienestar?", ["BIEN Sección 1"], ["BIEN Sección 1"]),
        ("Q8", "¿Qué requisitos tiene la beca por rendimiento académico?", ["BIEN Sección 3.1"], ["BIEN Sección 3.1"]),
