        ("C3", "¿Qué estudiantes están en prueba académica?", ["R25 Artículo 20"], ["R25 Artículo 20"]),
        ("E-b", "¿Estoy en prueba académica?", ["R25 Artículo 20"], ["R25 Artículo 20"]),
    };
