    foreach (var conExc in new[] { true, false })
    foreach (var u in new[] { 30, 35, 40, 45, 50, 55, 60, 70 })
    {
        int fe = 0, fr = 0, sobraNoRel = 0, sobraTot = 0;
        var det = new List<string>();
        foreach (var (etq, q, est, reg) in casos)
        {
            var rs = Puntajes(q).Take(6).ToList();
            var raicesP = RaicesDeContenido.De(q).ToHashSet();
            var minimo = Math.Min(2, (raicesP.Count + 1) / 2);
            bool Rel(SeccionDocumento s) => raicesP.Count > 0 && RaicesDeContenido.De($"{s.Titulo} {s.Texto}").Count(raicesP.Contains) >= minimo;
            var top = rs[0].P;
            var ent = rs.Where(x => 100 * x.P / top >= u || (conExc && Rel(x.S))).ToList();
            var ids = ent.Select(x => Id(x.S)).ToList();
            var f1 = est.Count(n => !ids.Contains(n));
            var f2 = reg.Count(n => !ids.Contains(n));
            fe += f1; fr += f2;
            sobraTot += ids.Count(i => !reg.Contains(i));
            sobraNoRel += ent.Count(x => !reg.Contains(Id(x.S)) && !Rel(x.S));
            det.Add($"{etq}:{ids.Count}" + (f1 > 0 ? $"!E{f1}" : "") + (f2 > 0 ? $"!R{f2}" : ""));
        }
        Console.WriteLine($"{u}% | {(conExc ? "con" : "sin")} | {string.Join(" ", det)} | faltanE={fe} faltanR={fr} sobraNoRel={sobraNoRel} sobraTot={sobraTot}");
    }
}
