using System.Reflection;
using System.Text;
using TutorFlow.Core.Asistente;
using TutorFlow.Core.Conocimiento;
using TutorFlow.Infrastructure.Conocimiento;

Console.OutputEncoding = Encoding.UTF8;
var opciones = new OpcionesConocimiento { DocumentosVigentes = ["reglamento_academico_2025.md", "evaluacion_y_calificaciones.md", "bienestar_y_becas.md"] };
var bc = CargadorConocimiento.Cargar(opciones);
var modo = args.Length > 0 ? args[0] : "recuperacion";

var t = typeof(BaseConocimientoEnMemoria);
var campo = t.GetField("_secciones", BindingFlags.NonPublic | BindingFlags.Instance)!;
var puntuar = t.GetMethod("Puntuar", BindingFlags.NonPublic | BindingFlags.Instance)!;
var extraer = t.GetMethod("ExtraerRaices", BindingFlags.NonPublic | BindingFlags.Static)!;
var expandir = t.Assembly.GetType("TutorFlow.Infrastructure.Conocimiento.ExpansionDeTerminos")!.GetMethod("Expandir")!;
var indexadas = ((System.Collections.IEnumerable)campo.GetValue(bc)!).Cast<object>().ToList();
var tipoIdx = indexadas[0].GetType();
var propSeccion = tipoIdx.GetProperty("Seccion")!;

List<(SeccionDocumento S, double P)> Puntajes(string pregunta)
{
    var consulta = ConsultaDeRecuperacion.DeTexto(pregunta);
    var raices = extraer.Invoke(null, [consulta])!;
    var frecs = (IReadOnlyDictionary<string, int>)raices.GetType().GetProperty("Frecuencias")!.GetValue(raices)!;
    var terminos = (IReadOnlyList<string>)expandir.Invoke(null, [frecs.Keys])!;
    return indexadas.Select(i => ((SeccionDocumento)propSeccion.GetValue(i)!, (double)puntuar.Invoke(bc, [i, terminos])!))
        .Where(x => x.Item2 > 0).OrderByDescending(x => x.Item2).ToList();
}

