import fs from 'node:fs';
const OUT = new URL('../crudo/3-contexto.jsonl', import.meta.url);
const base = 'Pérdida por inasistencia. El estudiante que falte a más del 15% de las clases programadas de una asignatura la pierde por inasistencia, con nota definitiva de 0.0, sin importar las notas obtenidas en los cortes. ';
const relleno = (n) => Array.from({ length: n }, (_, i) => `Sección ${i + 1}. ${base}`).join('\n');
const pregunta = 'Responde solo con la palabra FIN. El texto anterior es solo relleno.';
const msg = (n) => `Texto:\n${relleno(n)}\n\nPregunta: ${pregunta}`;

async function post(ruta, cuerpo) {
  const t0 = Date.now();
  const r = await fetch('http://localhost:11434' + ruta, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(cuerpo) });
  const j = await r.json();
  return { status: r.status, ms: Date.now() - t0, j };
}
const registrar = (etq, cuerpoResumen, res) => {
  const reg = { etq, cuerpo: cuerpoResumen, status: res.status, ms: res.ms, respuesta: res.j };
  fs.appendFileSync(OUT, JSON.stringify(reg) + '\n');
  const u = res.j.usage;
  console.log(etq, res.status, res.ms + 'ms', u ? `usage=${JSON.stringify(u)}` : `prompt_eval_count=${res.j.prompt_eval_count} eval_count=${res.j.eval_count} done_reason=${res.j.done_reason}`, res.j.error ? 'ERROR ' + JSON.stringify(res.j.error) : '', (res.j.choices?.[0]?.message?.content ?? res.j.message?.content ?? '').slice(0, 60));
};

const N = Number(process.argv[2] ?? 60);
const contenido = msg(N);
const comun = { model: 'qwen2.5:7b', temperature: 0, seed: 1 };

registrar('A0 /v1 sin opciones (contexto del servidor)', { N }, await post('/v1/chat/completions', { ...comun, messages: [{ role: 'user', content: contenido }], max_tokens: 8 }));
registrar('A1 /v1 con "options":{"num_ctx":1024}', { N }, await post('/v1/chat/completions', { ...comun, messages: [{ role: 'user', content: contenido }], max_tokens: 8, options: { num_ctx: 1024 } }));
registrar('A2 /v1 con "num_ctx":1024 de primer nivel', { N }, await post('/v1/chat/completions', { ...comun, messages: [{ role: 'user', content: contenido }], max_tokens: 8, num_ctx: 1024 }));
registrar('B0 /api/chat sin num_ctx', { N }, await post('/api/chat', { ...comun, stream: false, messages: [{ role: 'user', content: contenido }], options: { temperature: 0, seed: 1, num_predict: 8 } }));
registrar('B1 /api/chat options.num_ctx=1024', { N }, await post('/api/chat', { ...comun, stream: false, messages: [{ role: 'user', content: contenido }], options: { temperature: 0, seed: 1, num_predict: 8, num_ctx: 1024 } }));
registrar('B2 /api/chat options.num_ctx=4096', { N }, await post('/api/chat', { ...comun, stream: false, messages: [{ role: 'user', content: contenido }], options: { temperature: 0, seed: 1, num_predict: 8, num_ctx: 4096 } }));
registrar('B3 /api/chat options.num_ctx=32768', { N }, await post('/api/chat', { ...comun, stream: false, messages: [{ role: 'user', content: contenido }], options: { temperature: 0, seed: 1, num_predict: 8, num_ctx: 32768 } }));

