const CONECT = ['segun', 'de acuerdo con', 'conforme a', 'conforme al', 'proviene de', 'proviene del', 'provienen de', 'provienen del', 'se basa en', 'se basan en', 'basado en', 'basada en', 'basados en', 'basadas en', 'se encuentra en', 'se encuentran en', 'respaldado por', 'respaldada por', 'respaldados por', 'respaldadas por', 'se respalda en', 'se respaldan en', 'establecido en', 'establecida en', 'establecidos en', 'establecidas en'];
