const resultados = [];
for (const archivo of ['diag.jsonl', 'diag-T0.jsonl', 'diag-REQ.jsonl']) {
  const L = fs.readFileSync(DIR + archivo, 'utf8').split('\n').filter(Boolean).map(JSON.parse);
