      for (const m of n.matchAll(RE)) {
        const doc = DESC.find((d) => d[0] === m[2])[1];
        const enCand = cand.some((c) => c.startsWith(doc));
        const enFinal = (fin?.datos.citas ?? []).some((c) => c.startsWith(doc));
        resultados.push({ archivo, peticion: id.slice(-6), usuario: ini.datos.usuario, pregunta: ini.datos.pregunta, fragmento: texto.slice(Math.max(0, m.index - 20), m.index + m[0].length + 20).replace(/\n/g, ' '), doc, citaEscritaValida: enCand, citaFinalDelDoc: enFinal, resultadoFinal: fin?.datos.resultado, citasFinales: fin?.datos.citas });
      }
    }
  }
}
