import fs from 'node:fs';
const L = fs.readFileSync(new URL('../crudo/4-corridas.jsonl', import.meta.url), 'utf8').trim().split('\n').map(JSON.parse);
const grupos = new Map();
for (const r of L) {
  const k = `${r.clave}|${r.variante}|${r.temp}`;
  if (!grupos.has(k)) grupos.set(k, []);
  grupos.get(k).push(r);
}
const norm = (s) => s.replace(/\s+/g, ' ').trim();
console.log('clave | variante | T | semilla1x5: n, distintos | (T>0) semillas1-5: n, distintos | aciertos por métrica (semilla 1 x5 / semillas variadas) | tool_calls | prompt_tokens');
for (const [k, rs] of grupos) {
  const [clave, variante, temp] = k.split('|');
  const fija = rs.slice(0, 5);
  const variadas = Number(temp) > 0 ? [rs[0], ...rs.slice(5)] : [];
  const metricas = Object.keys(rs[0].medicion);
  const cuenta = (arr, m) => `${arr.filter((r) => r.medicion[m]).length}/${arr.length}`;
  const fila = metricas.map((m) => `${m}=${cuenta(fija, m)}${variadas.length ? ' / ' + cuenta(variadas, m) : ''}`).join(', ');
  const d1 = new Set(fija.map((r) => norm(r.texto))).size;
  const d2 = variadas.length ? new Set(variadas.map((r) => norm(r.texto))).size : '-';
  console.log(`${clave} | ${variante} | ${temp} | ${fija.length}, ${d1} | ${variadas.length || '-'}, ${d2} | ${fila} | ${rs.filter((r) => r.tool_calls).length} | ${rs[0].usage?.prompt_tokens}`);
}

