using TutorFlow.Core.Asistente;
using TutorFlow.Core.Conocimiento;

public static class Apoyo
{
    public static void Ejecutar(Func<string, List<(SeccionDocumento S, double P)>> puntajes, Func<SeccionDocumento, string> id, string pregunta, string archivoTextos)
    {
        var textos = File.ReadAllLines(archivoTextos).Where(l => !string.IsNullOrWhiteSpace(l)).ToList();
        var ranking = puntajes(pregunta).Take(6).ToList();
        var top = ranking[0].P;
        var raicesP = RaicesDeContenido.De(pregunta).ToHashSet();
        var minimo = Math.Min(2, (raicesP.Count + 1) / 2);
        bool Rel(SeccionDocumento s) => RaicesDeContenido.De($"{s.Titulo} {s.Texto}").Count(raicesP.Contains) >= minimo;
        var entregadas = ranking.Where(x => 100 * x.P / top >= 50 || Rel(x.S)).Select(x => x.S).ToList();
        Console.WriteLine("Entregadas con umbral 50% + excepcion de relevancia: " + string.Join("; ", entregadas.Select(id)));
        var n = 0;
        foreach (var texto in textos)
        {
            n++;
            var sinCitas = ExtractorCitas.SinCitas(texto);
            var raicesResp = RaicesDeContenido.DeApoyo(sinCitas).ToHashSet(StringComparer.Ordinal);
            Console.WriteLine($"\n[{n}] {texto.Replace("\n", " ")}");
            Console.WriteLine("raices respuesta: " + string.Join(",", raicesResp.OrderBy(x => x)));
            var filas = entregadas.Select((s, i) =>
            {
                var compartidas = RaicesDeContenido.DeApoyo($"{s.Titulo} {s.Texto}").Where(raicesResp.Contains).Distinct().ToList();
                return (Rank: i + 1, S: s, Compartidas: compartidas);
            }).ToList();
            var max = filas.Max(f => f.Compartidas.Count);
            foreach (var f in filas)
            {
                Console.WriteLine($"  rank {f.Rank} {id(f.S)} apoyo={f.Compartidas.Count} ({100 * f.Compartidas.Count / Math.Max(max, 1)}% del max) [{string.Join(",", f.Compartidas)}]");
            }
            var actual = filas.Where(f => f.Compartidas.Count >= 2).Take(2).Select(f => id(f.S));
            var d49 = filas.Where(f => f.Compartidas.Count >= 2).OrderByDescending(f => f.Compartidas.Count).ThenBy(f => f.Rank).Take(1).Select(f => id(f.S));
            Console.WriteLine($"  respaldo ACTUAL (2 primeras con apoyo>=2): [{string.Join("; ", actual)}]");
            Console.WriteLine($"  respaldo D-49 (1, mayor apoyo): [{string.Join("; ", d49)}]");
            foreach (var pct in new[] { 50, 60, 70 })
            {
                var alt = filas.Where(f => f.Compartidas.Count >= 2 && 100 * f.Compartidas.Count >= pct * max).OrderByDescending(f => f.Compartidas.Count).ThenBy(f => f.Rank).Take(2).Select(f => id(f.S));
                Console.WriteLine($"  respaldo ALT-2 con apoyo>={pct}% del max: [{string.Join("; ", alt)}]");
            }
        }
    }
}

