  ]).map((h) => ({ type: 'function', function: { name: h.n, description: h.d, parameters: { type: 'object', properties: Object.fromEntries(Object.entries(h.p).map(([k, v]) => [k, { type: 'string', description: v }])), required: Object.keys(h.p) } } }));

