import fs from 'node:fs';
import { escenario } from './datos.mjs';
const DIAG = 'C:/Users/usuario/AppData/Local/Temp/claude/081ea1635fc6c07b/d9992a1c-1222-4795-8987-afdf1a8020db/scratchpad/ronda4/diag-logs/diag-T0.jsonl';
const viejos = fs.readFileSync(DIAG, 'utf8').split('\n').filter(Boolean).map(JSON.parse).filter((l) => l.tipo === 'entrada_modelo');
const sistemaViejoCoord = viejos.find((l) => l.datos.prompt_sistema.includes('Hablas con un coordinador')).datos.prompt_sistema;
const sistemaViejoEst = viejos.find((l) => l.datos.prompt_sistema.includes('Hablas con un estudiante')).datos.prompt_sistema;

async function post(ruta, cuerpo) {
  const r = await fetch('http://localhost:11434' + ruta, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(cuerpo) });
  return r.json();
}
const filas = [];
for (const [clave, variante] of [['P6', 'A'], ['C1', 'A'], ['C2', 'A'], ['C3', 'A'], ['P6', 'F'], ['P2', 'F'], ['P5', 'F']]) {
  for (const prompt of ['nuevo-9.5', 'viejo-v1.10']) {
    const esc = escenario(clave, variante);
    const system = prompt === 'nuevo-9.5' ? esc.system : (esc.rol === 'coordinador' ? sistemaViejoCoord : sistemaViejoEst);
    const mensajes = [{ role: 'system', content: system }, { role: 'user', content: esc.user }];
    const chars = system.length + esc.user.length + JSON.stringify(esc.tools).length;
    const v1 = await post('/v1/chat/completions', { model: 'qwen2.5:7b', temperature: 0, seed: 1, max_tokens: 1, messages: mensajes, tools: esc.tools });
    const nat = await post('/api/chat', { model: 'qwen2.5:7b', stream: false, messages: mensajes, tools: esc.tools, options: { temperature: 0, seed: 1, num_predict: 1, num_ctx: 4096 } });
    filas.push({ clave, variante, prompt, chars, estimado_chars_3_5: Math.round(chars / 3.5), tokens_v1_ctx_servidor: v1.usage?.prompt_tokens, tokens_native_num_ctx_4096: nat.prompt_eval_count, truncado_en_4096: nat.prompt_eval_count < v1.usage?.prompt_tokens });
    console.log(JSON.stringify(filas.at(-1)));
  }
}
fs.writeFileSync(new URL('../crudo/3-tokens.json', import.meta.url), JSON.stringify(filas, null, 1));

